import {cornerSettings,KERB_MODES} from './corner-settings.js';
const $=s=>document.querySelector(s);
export function mountCorners(api){
  const panel=document.createElement('section');panel.className='panel-section corner-panel';panel.innerHTML=`<div class="section-heading"><span class="section-num">TURN</span><h2>Corner workshop</h2><span id="corner-number" class="scene-tag"></span></div><p id="corner-empty" class="field-hint">Click a road handle or choose a point below to customize a corner.</p><div class="corner-navigation"><button id="previous-corner" class="outline-button" aria-label="Previous corner point">←</button><select id="corner-select" aria-label="Choose corner control point"></select><button id="next-corner" class="outline-button" aria-label="Next corner point">→</button></div><div id="corner-controls" hidden><label class="studio-field">Corner name<input id="corner-name" maxlength="40" placeholder="e.g. Sunset hairpin"></label><div class="corner-shapes" role="group" aria-label="Corner shape"><button data-rounding="0">Sharp</button><button data-rounding=".35">Tight</button><button data-rounding="1">Rounded</button></div><label class="studio-field">Rounding <span id="rounding-value"></span><input id="corner-rounding" type="range" min="0" max="100" step="1"></label><div class="corner-profile" id="corner-profile" aria-hidden="true"></div><div class="studio-fields"><label class="studio-field">Kerbs<select id="corner-kerbs">${Object.entries(KERB_MODES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label class="studio-field">Kerb width · meters<input id="corner-kerb-width" type="number" min=".25" max="2" step=".05"></label></div><label class="studio-field">Banking · degrees<input id="corner-banking" type="number" min="-15" max="15" step=".5"></label><button id="reset-corner" class="outline-button">Reset corner settings</button><p id="corner-hint" class="field-hint"></p></div>`;
  $('.point-section').after(panel);let lastPoints='';
  const select=index=>{const t=api.getTrack();if(!t.points.length)return;api.selectPoint((index+t.points.length)%t.points.length);};$('#corner-select').onchange=()=>select(Number($('#corner-select').value));$('#previous-corner').onclick=()=>select(Math.max(0,api.getSelected())-1);$('#next-corner').onclick=()=>select(api.getSelected()+1);
  const change=(key,value)=>{const i=api.getSelected();if(i<0)return;api.updateTrack(t=>{t.points[i][key]=value;});};$('#corner-name').onchange=()=>change('cornerName',$('#corner-name').value.trim());
  panel.querySelectorAll('[data-rounding]').forEach(b=>b.onclick=()=>change('rounding',Number(b.dataset.rounding)));
  $('#corner-rounding').oninput=()=>$('#rounding-value').textContent=`${$('#corner-rounding').value}%`;
  $('#corner-rounding').onchange=()=>change('rounding',Number($('#corner-rounding').value)/100);
  $('#corner-kerbs').onchange=()=>change('kerbs',$('#corner-kerbs').value);
  for(const [id,key,min,max] of [['corner-kerb-width','kerbWidth',.25,2],['corner-banking','bank',-15,15]])$('#'+id).onchange=()=>{const v=Number($('#'+id).value);if(!Number.isFinite(v)||v<min||v>max){api.toast(`Enter a value between ${min} and ${max}.`);refresh();return;}change(key,v);};
  $('#reset-corner').onclick=()=>{const i=api.getSelected();if(i>=0)api.updateTrack(t=>{Object.assign(t.points[i],cornerSettings());t.points[i].bank=0;});};
  function refresh(){const t=api.getTrack(),i=api.getSelected(),p=t.points[i],key=t.points.map(p=>p.cornerName||'').join('|')+t.points.length;$('#previous-corner').disabled=$('#next-corner').disabled=!t.points.length;$('#corner-select').disabled=!t.points.length;if(key!==lastPoints){lastPoints=key;$('#corner-select').replaceChildren();const placeholder=document.createElement('option');placeholder.value='-1';placeholder.textContent='Choose a control point';placeholder.disabled=true;$('#corner-select').append(placeholder);t.points.forEach((p,j)=>{const o=document.createElement('option');o.value=j;o.textContent=`${String(j+1).padStart(2,'0')} · ${p.cornerName||'Corner point'}`;$('#corner-select').append(o);});}$('#corner-select').value=String(p?i:-1);$('#corner-controls').hidden=!p;$('#corner-empty').hidden=!!p;$('#corner-number').textContent=p?`POINT ${i+1}`:'';if(!p)return;const c=cornerSettings(p);$('#corner-name').value=c.cornerName;$('#corner-rounding').value=Math.round(c.rounding*100);$('#rounding-value').textContent=`${Math.round(c.rounding*100)}%`;$('#corner-kerbs').value=c.kerbs;$('#corner-kerb-width').value=c.kerbWidth;$('#corner-banking').value=p.bank||0;panel.querySelectorAll('[data-rounding]').forEach(b=>b.classList.toggle('active',Math.abs(Number(b.dataset.rounding)-c.rounding)<.01));const r=c.rounding*45;$('#corner-profile').innerHTML=`<svg viewBox="0 0 200 85"><path d="M15 70H${100-r}Q100 70 100 ${70-r}V15" fill="none" stroke="#526759" stroke-width="10" stroke-linecap="round"/><path d="M15 70H${100-r}Q100 70 100 ${70-r}V15" fill="none" stroke="#eee7c6" stroke-width="1" stroke-dasharray="3 5"/><circle cx="100" cy="70" r="4" fill="#eb955a"/><text x="130" y="45">${Math.round(c.rounding*100)}%</text></svg>`;$('#corner-hint').textContent=(t.smooth?'Rounding changes the curve at this handle. ':'Enable Smooth corners to see rounding. ')+(t.export?.kerbs===false?'Enable Generate kerbs in Assetto Corsa setup to show kerbs.':'Kerb settings apply to the outgoing section. Changes appear in 3D and export.');}
  return {refresh};
}
